    redirect: (status: number, path: string) => {
      redirectUrl = path;
      const err = new Error(`Redirect to ${path}`);
      (err as any).status = status;
      (err as any).path = path;
      (err as any).isRedirect = true;
      throw err;
    },
    status: (code: number) => {
      statusCode = code;
    },
    get_statusCode: () => statusCode,
    get_redirectUrl: () => redirectUrl,
  } as any;
};

async function runTests() {
  console.log('--- Starting RBAC Tests ---');

  // 1. Test Database Operations
